4	import type { AppEventType } from "@motion-studio/shared";
5	import { createEditorKernel } from "../editor-kernel/create-editor-kernel";
6	import type { EditorKernel } from "../editor-kernel/editor-kernel";
7	import { useEngineRevisionStore } from "../state/use-engine-revision-store";
8	
9	const EditorKernelContext = createContext<EditorKernel | null>(null);
10	
11	/** Every event whose real effect is "something a panel reads via selectors just changed." */
12	const REVISION_EVENTS: readonly AppEventType[] = [
13	  "CommandExecuted",
14	  "CommandUndone",
15	  "CommandRedone",
16	  "AssetImported",
17	  "AssetDeleted",
18	  "PluginActivated",
19	];
20	
21	/**
22	 * Constructs the `EditorKernel` once per mount — browser-only (opens real
23	 * IndexedDB/OPFS), so this must run client-side, never during SSR. Bumps
24	 * `useEngineRevisionStore` on every project-mutating event so panels
25	 * re-read the engines; project data itself never gets copied into React
26	 * state (PLAN.md 15.7).
27	 */
28	export function EditorKernelProvider({ children }: { children: ReactNode }): JSX.Element {
29	  const [kernel, setKernel] = useState<EditorKernel | null>(null);
30	  const [error, setError] = useState<Error | null>(null);
