140	/**
141	 * Fixed flex layout (CapCut-style reskin, M11) — Toolbar, IconRail+LeftPanel,
142	 * Canvas+PlaybackBar, Timeline each in a static region. No dockable
143	 * Split/Stack/Panel tree, no layout-undo (ADR-011) — `docs/17-ui/docking.md`'s
144	 * real engine is deferred to its own future pass (Phase 15 scope decision).
145	 * The Inspector is the one floating exception: it overlays the canvas
146	 * region and only mounts when something is selected, matching the
147	 * reference screenshot's lack of persistent right-side chrome.
148	 */
149	export function EditorShell(): JSX.Element {
150	  const kernel = useEditorKernel();
151	  const hasSelection = useTimelineStore((state) => state.selection.layerIds.length > 0);
152	  // Without an activation distance, `PointerSensor` starts a drag on the
153	  // very first pointermove, which swallows the click a plain selection tap
154	  // on a clip/asset tile needs — 4px matches dnd-kit's own recommended
155	  // default for this exact click-vs-drag ambiguity.
156	  const sensors = useSensors(useSensor(PointerSensor, { activationConstraint: { distance: 4 } }));
157	
