13	import { TrackRegistry } from "./track-registry";
14	
15	/**
16	 * Owns the "when" (CLAUDE.md engine ownership table): Composition → Track →
17	 * TrackItem, referencing Layers by id only. Never touches rendering,
18	 * decoding, or storage — see ARCHITECTURE.md §3. Composes the three
19	 * registries and is the only thing allowed to mutate `IComposition.tracks`
20	 * or `ITrack.items` after creation, so those arrays can never drift out of
21	 * sync with the registries.
22	 */
23	export class TimelineEngine implements IEngine {
24	  readonly name = "Timeline";
25	  readonly compositions = new CompositionRegistry();
26	  readonly tracks = new TrackRegistry();
27	  readonly trackItems = new TrackItemRegistry();
28	
29	  initialize(): void {
30	    // No async setup required — registries are ready on construction.
31	  }
32	
33	  ready(): void {}
34	
35	  dispose(): void {
36	    this.compositions.clear();
37	    this.tracks.clear();
38	    this.trackItems.clear();
39	  }
40	
41	  addTrack(compositionId: CompositionId, track: ITrack): void {
42	    const composition = this.requireComposition(compositionId);
43	    this.tracks.add(track);
44	    composition.tracks = [...composition.tracks, track.id];
45	  }
46	
47	  /** Fails fast if the track still has items — callers must remove/move them first, mirroring `CompositionGraph.removeLayer`. */
48	  removeTrack(compositionId: CompositionId, trackId: TrackId): void {
49	    const composition = this.requireComposition(compositionId);
50	    const track = this.requireTrack(trackId);
51	    if (track.items.length > 0) {
52	      throw new Error(
53	        `TimelineEngine: cannot remove track "${trackId}" — it still has items; remove them first.`,
