1	import { RenderBackend } from "@motion-studio/shared";
2	import { placeholderColor } from "./placeholder-color";
3	import type { IRenderBackend, IRenderTargetSize } from "./render-backend";
4	import { sortRenderQueue } from "./render-queue";
5	import type { ISceneGraph, ISceneGraphNode } from "./scene-graph";
6	
7	export type IGPUShaderModule = object;
8	export type IGPUBuffer = object;
9	export type IGPUBindGroupLayout = object;
10	export type IGPUBindGroup = object;
11	export type IGPUTextureView = object;
12	export type IGPUCommandBuffer = object;
13	
14	export interface IGPURenderPipeline {
15	  getBindGroupLayout(index: number): IGPUBindGroupLayout;
16	}
17	
18	export interface IGPURenderPassEncoder {
19	  setPipeline(pipeline: IGPURenderPipeline): void;
20	  setVertexBuffer(slot: number, buffer: IGPUBuffer): void;
21	  setBindGroup(index: number, bindGroup: IGPUBindGroup): void;
22	  draw(vertexCount: number): void;
23	  end(): void;
24	}
25	
26	export interface IGPUCommandEncoder {
27	  beginRenderPass(descriptor: {
28	    colorAttachments: ReadonlyArray<{
29	      view: IGPUTextureView;
30	      clearValue: { r: number; g: number; b: number; a: number };
31	      loadOp: "clear" | "load";
32	      storeOp: "store" | "discard";
33	    }>;
34	  }): IGPURenderPassEncoder;
35	  finish(): IGPUCommandBuffer;
36	}
37	
38	export interface IGPUQueue {
39	  writeBuffer(buffer: IGPUBuffer, bufferOffset: number, data: Float32Array): void;
40	  submit(commandBuffers: readonly IGPUCommandBuffer[]): void;
41	}
42	
43	export interface IGPUCanvasContext {
44	  configure(config: { device: IGPUDevice; format: string }): void;
45	  getCurrentTexture(): { createView(): IGPUTextureView };
46	}
47	
48	/**
49	 * The subset of `GPUDevice` this backend calls — hand-rolled (there is no
50	 * `@webgpu/types` dependency here) so tests can inject a fake without a
51	 * real GPU, same pattern as `IWebGL2Context`/`ICanvas2DContext`.
52	 */
53	export interface IGPUDevice {
54	  readonly queue: IGPUQueue;
55	  createShaderModule(descriptor: { code: string }): IGPUShaderModule;
56	  createBuffer(descriptor: { size: number; usage: number }): IGPUBuffer;
57	  createRenderPipeline(descriptor: {
58	    layout: "auto";
59	    vertex: {
60	      module: IGPUShaderModule;
61	      entryPoint: string;
62	      buffers: ReadonlyArray<{
63	        arrayStride: number;
64	        attributes: ReadonlyArray<{ shaderLocation: number; offset: number; format: string }>;
65	      }>;
66	    };
67	    fragment: {
68	      module: IGPUShaderModule;
69	      entryPoint: string;
70	      targets: ReadonlyArray<{ format: string }>;
71	    };
72	    primitive: { topology: string };
73	  }): IGPURenderPipeline;
74	  createBindGroup(descriptor: {
75	    layout: IGPUBindGroupLayout;
76	    entries: ReadonlyArray<{ binding: number; resource: { buffer: IGPUBuffer } }>;
77	  }): IGPUBindGroup;
78	  createCommandEncoder(): IGPUCommandEncoder;
79	}
80	
81	export interface IWebGPUBackendDependencies {
82	  getDevice(): IGPUDevice;
83	  getCanvasContext(): IGPUCanvasContext;
84	  /** Defaults to `"bgra8unorm"`, the platform-preferred swap chain format on most browsers. */
85	  canvasFormat?: string;
86	}
87	
88	// WebGPU spec-fixed GPUBufferUsage bit flags — not exposed on GPUDevice itself.
89	const GPU_BUFFER_USAGE_VERTEX = 0x20;
90	const GPU_BUFFER_USAGE_UNIFORM = 0x40;
91	const GPU_BUFFER_USAGE_COPY_DST = 0x8;
92	
93	const UNIFORM_BUFFER_SIZE_BYTES = 64; // 16 floats — see struct layout in WGSL_SHADER_SOURCE below.
94	const UNIFORM_FLOAT_COUNT = UNIFORM_BUFFER_SIZE_BYTES / 4;
95	
96	const UNIT_QUAD = new Float32Array([0, 0, 1, 0, 0, 1, 1, 1]);
97	
98	/**
99	 * Single WGSL module (vertex + fragment) mirroring `webgl2-backend.ts`'s
100	 * GLSL topology exactly, but authored independently per ADR-004/
101	 * shader-system.md: WGSL and GLSL are never auto-shared. Struct field
102	 * order/alignment matches the 16-float `Float32Array` written per node in
103	 * `writeUniforms` below (`vec2`/`f32` @ 8/4-byte alignment, `vec4` @
104	 * 16-byte alignment per the WGSL spec).
105	 */
106	const WGSL_SHADER_SOURCE = `
107	struct Uniforms {
108	  canvasSize: vec2<f32>,
109	  translate: vec2<f32>,
110	  scale: vec2<f32>,
111	  rotation: f32,
112	  _pad0: f32,
113	  boundsOrigin: vec2<f32>,
114	  boundsSize: vec2<f32>,
115	  color: vec4<f32>,
116	};
117	@group(0) @binding(0) var<uniform> u: Uniforms;
118	
119	@vertex
120	fn vs_main(@location(0) unitQuad: vec2<f32>) -> @builtin(position) vec4<f32> {
121	  let local = u.boundsOrigin + unitQuad * u.boundsSize;
122	  let scaled = local * u.scale;
123	  let c = cos(u.rotation);
124	  let s = sin(u.rotation);
125	  let rotated = vec2<f32>(scaled.x * c - scaled.y * s, scaled.x * s + scaled.y * c);
126	  let world = rotated + u.translate;
127	  let ndc = (world / u.canvasSize) * 2.0 - vec2<f32>(1.0, 1.0);
128	  return vec4<f32>(ndc.x, -ndc.y, 0.0, 1.0);
129	}
130	
131	@fragment
132	fn fs_main() -> @location(0) vec4<f32> {
133	  return u.color;
134	}
135	`;
136	
137	/** WebGPU backend — the primary rung (`05-rendering-engine/webgpu.md`), confirmed solid 2026 browser support. */
138	export class WebGPURenderBackend implements IRenderBackend {
139	  readonly kind = RenderBackend.WebGPU;
140	
141	  private readonly dependencies: IWebGPUBackendDependencies;
142	  private device: IGPUDevice | null = null;
143	  private canvasContext: IGPUCanvasContext | null = null;
144	  private pipeline: IGPURenderPipeline | null = null;
145	  private vertexBuffer: IGPUBuffer | null = null;
146	  private uniformBuffer: IGPUBuffer | null = null;
147	  private bindGroup: IGPUBindGroup | null = null;
148	  private width = 0;
149	  private height = 0;
150	
151	  constructor(dependencies: IWebGPUBackendDependencies) {
152	    this.dependencies = dependencies;
153	  }
154	
155	  init(target: IRenderTargetSize): void {
156	    this.width = target.width;
157	    this.height = target.height;
158	
159	    const device = this.dependencies.getDevice();
160	    const canvasContext = this.dependencies.getCanvasContext();
161	    const format = this.dependencies.canvasFormat ?? "bgra8unorm";
162	    canvasContext.configure({ device, format });
163	
164	    const shaderModule = device.createShaderModule({ code: WGSL_SHADER_SOURCE });
165	    const pipeline = device.createRenderPipeline({
166	      layout: "auto",
167	      vertex: {
168	        module: shaderModule,
169	        entryPoint: "vs_main",
170	        buffers: [
171	          { arrayStride: 8, attributes: [{ shaderLocation: 0, offset: 0, format: "float32x2" }] },
172	        ],
173	      },
174	      fragment: { module: shaderModule, entryPoint: "fs_main", targets: [{ format }] },
175	      primitive: { topology: "triangle-strip" },
176	    });
177	
178	    const vertexBuffer = device.createBuffer({
179	      size: UNIT_QUAD.byteLength,
180	      usage: GPU_BUFFER_USAGE_VERTEX | GPU_BUFFER_USAGE_COPY_DST,
181	    });
182	    device.queue.writeBuffer(vertexBuffer, 0, UNIT_QUAD);
183	
184	    const uniformBuffer = device.createBuffer({
185	      size: UNIFORM_BUFFER_SIZE_BYTES,
186	      usage: GPU_BUFFER_USAGE_UNIFORM | GPU_BUFFER_USAGE_COPY_DST,
187	    });
188	    const bindGroup = device.createBindGroup({
189	      layout: pipeline.getBindGroupLayout(0),
190	      entries: [{ binding: 0, resource: { buffer: uniformBuffer } }],
191	    });
192	
193	    this.device = device;
194	    this.canvasContext = canvasContext;
195	    this.pipeline = pipeline;
196	    this.vertexBuffer = vertexBuffer;
197	    this.uniformBuffer = uniformBuffer;
198	    this.bindGroup = bindGroup;
199	  }
200	
201	  drawFrame(sceneGraph: ISceneGraph): void {
202	    const device = this.requireDevice();
203	    const canvasContext = this.requireCanvasContext();
204	    const pipeline = this.requirePipeline();
205	    const encoder = device.createCommandEncoder();
206	    const view = canvasContext.getCurrentTexture().createView();
207	
208	    const pass = encoder.beginRenderPass({
209	      colorAttachments: [
210	        { view, clearValue: { r: 0, g: 0, b: 0, a: 0 }, loadOp: "clear", storeOp: "store" },
211	      ],
212	    });
213	    pass.setPipeline(pipeline);
214	    pass.setVertexBuffer(0, this.vertexBuffer as IGPUBuffer);
215	    pass.setBindGroup(0, this.bindGroup as IGPUBindGroup);
216	
217	    for (const node of sortRenderQueue(sceneGraph.nodes)) {
218	      this.writeUniforms(device, node);
219	      pass.draw(4);
220	    }
221	
222	    pass.end();
223	    device.queue.submit([encoder.finish()]);
224	  }
225	
226	  dispose(): void {
227	    this.device = null;
228	    this.canvasContext = null;
229	    this.pipeline = null;
230	    this.vertexBuffer = null;
231	    this.uniformBuffer = null;
232	    this.bindGroup = null;
233	  }
234	
235	  private writeUniforms(device: IGPUDevice, node: ISceneGraphNode): void {
236	    const { r, g, b } = placeholderColor(node.layerId);
237	    const { transform, bounds } = node;
238	    const data = new Float32Array(UNIFORM_FLOAT_COUNT);
239	    data[0] = this.width;
240	    data[1] = this.height;
241	    data[2] = transform.x;
242	    data[3] = transform.y;
243	    data[4] = transform.scaleX;
244	    data[5] = transform.scaleY;
245	    data[6] = transform.rotation;
246	    data[7] = 0; // _pad0
247	    data[8] = bounds.x - transform.anchorX;
248	    data[9] = bounds.y - transform.anchorY;
249	    data[10] = bounds.width;
250	    data[11] = bounds.height;
251	    data[12] = r / 255;
252	    data[13] = g / 255;
253	    data[14] = b / 255;
254	    data[15] = node.opacity;
255	    device.queue.writeBuffer(this.uniformBuffer as IGPUBuffer, 0, data);
256	  }
257	
258	  private requireDevice(): IGPUDevice {
259	    if (!this.device) {
260	      throw new Error("WebGPURenderBackend: drawFrame called before init()");
261	    }
262	    return this.device;
263	  }
264	
265	  private requireCanvasContext(): IGPUCanvasContext {
266	    if (!this.canvasContext) {
267	      throw new Error("WebGPURenderBackend: drawFrame called before init()");
268	    }
269	    return this.canvasContext;
270	  }
271	
272	  private requirePipeline(): IGPURenderPipeline {
273	    if (!this.pipeline) {
274	      throw new Error("WebGPURenderBackend: drawFrame called before init()");
275	    }
276	    return this.pipeline;
277	  }
278	}
279

